(()=>{'use strict';const lang=document.documentElement.lang.startsWith('ko')?'ko':'en',map=GGD_ROUTES[lang];function urlFor(route){try{route=decodeURIComponent(route)}catch{}if(map[route])return map[route];if(route.startsWith('search/'))return map.search+'?q='+encodeURIComponent(route.slice(7));if(lang==='ko'&&route.startsWith('trainingsheet/')){const p=route.split('/');if(map[p.slice(0,2).join('/')])return map[p.slice(0,2).join('/')]+(p[2]?'?layout='+encodeURIComponent(p[2]):'')}if(lang==='en'&&route.startsWith('standards/'))return '/en/library.html#'+route;return null}function convert(){document.querySelectorAll('a[href^="#"]').forEach(a=>{const raw=a.getAttribute('href').slice(1);if(raw==='main'){a.href=location.pathname+'#main';return}const url=urlFor(raw);if(url)a.setAttribute('href',url)});document.querySelectorAll('#content iframe').forEach(f=>{f.loading='lazy';if(!f.title)f.title=lang==='ko'?'문제지와 인쇄 화면':'Worksheet and printing'});}function oldHash(){const hash=location.hash.slice(1);if(!hash||hash==='main'||hash==='worksheet-player')return;const url=urlFor(hash);if(url&&!(location.pathname==='/en/library.html'&&url.startsWith('/en/library.html#'))&&new URL(url,location.origin).href!==location.href)location.replace(url)}oldHash();addEventListener('hashchange',oldHash);convert();const content=document.querySelector('#content');if(content)new MutationObserver(convert).observe(content,{childList:true,subtree:true});document.querySelector('.worksheet-search')?.addEventListener('submit',e=>{e.preventDefault();e.stopImmediatePropagation();const q=document.querySelector('#worksheet-query').value.trim();location.href=map.search+'?q='+encodeURIComponent(q)},true);})();
